style.css:
@-moz-document domain("pinterest.com"), domain("pinterest.ru") {
body, 
    .App, 
    [data-test-id="viva-dark-mode-provider"],
    [data-test-id="header"],
    .HeaderContainer {
        background-color: #120c1f !important;
        color: #e2dbf0 !important;
    }
    
    [data-test-id="pin"] {
        background-color: #1a122c !important;
        border: 1px solid #3d2663 !important;
        border-radius: 18px !important;
        box-shadow: 0 4px 15px rgba(138, 43, 226, 0.15) !important;
        transition: transform 0.2s ease, box-shadow 0.2s ease !important;
    }

    [data-test-id="pin"]:hover {
        transform: translateY(-2px) !important;
        box-shadow: 0 6px 20px rgba(186, 85, 211, 0.4) !important;
    }

    [data-test-id="killer-save-button"],
    [data-test-id="board-share-button"],
    button[class*="rounded"] {
        background-color: #8a2be2 !important;
        color: #ffffff !important;
    }
    
    [data-test-id="killer-save-button"]:hover,
    button[class*="rounded"]:hover {
        background-color: #ba55d3 !important;
        box-shadow: 0 0 10px #ba55d3 !important;
    }

    [data-test-id="search-box-input"],
    [data-test-id="search-bar"] {
        background-color: #24193d !important;
        border: 1px solid #5a3d8c !important;
        color: #ffffff !important;
    }

    [data-test-id="pin-title"], 
    span, 
    h1, 
    h2, 
    div {
        color: #e2dbf0 !important;
    }
    
    a, [class*="active"] {
        color: #da70d6 !important;
    }
}
